import { createContext, useContext, useState } from "react";

const InventoryContext = createContext();

const initialInventory = [
  { id: 1, name: "Pizza", price: 199, stock: 10 },
  { id: 2, name: "Burger", price: 99, stock: 15 },
  { id: 3, name: "Sandwich", price: 79, stock: 20 },
];

export function InventoryProvider({ children }) {
  const [inventory, setInventory] = useState(initialInventory);

  const deductInventory = (items) => {
    setInventory(prev =>
      prev.map(item => {
        const count = items.filter(i => i.id === item.id).length;
        return count
          ? { ...item, stock: item.stock - count }
          : item;
      })
    );
  };

  return (
    <InventoryContext.Provider value={{ inventory, deductInventory }}>
      {children}
    </InventoryContext.Provider>
  );
}

export const useInventory = () => useContext(InventoryContext);
